-- Settlement SMS (ADR-0216): WeSend's sealed key, the batches staff send and each customer's frozen
-- text. Only adds tables. Generated by drizzle-kit; by hand: the REVOKEs and column grants at the end,
-- which keep a batch's template and a message's number, text and balance as they were written.
CREATE TABLE "sms_batches" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "sms_batches_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"purpose" text NOT NULL,
	"settlement_group" text,
	"template" text NOT NULL,
	"status" text DEFAULT 'QUEUED' NOT NULL,
	"total_count" integer NOT NULL,
	"sent_count" integer DEFAULT 0 NOT NULL,
	"failed_count" integer DEFAULT 0 NOT NULL,
	"skipped_count" integer DEFAULT 0 NOT NULL,
	"credits_used" integer DEFAULT 0 NOT NULL,
	"stopped_code" text,
	"created_by" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"started_at" timestamp with time zone,
	"finished_at" timestamp with time zone,
	CONSTRAINT "sms_batches_purpose" CHECK ("sms_batches"."purpose" IN ('SETTLEMENT')),
	CONSTRAINT "sms_batches_status" CHECK ("sms_batches"."status" IN ('QUEUED', 'SENDING', 'DONE')),
	CONSTRAINT "sms_batches_group" CHECK ("sms_batches"."settlement_group" IS NULL OR "sms_batches"."settlement_group" IN ('DAY_20', 'MONTH_END')),
	CONSTRAINT "sms_batches_template" CHECK (length(btrim("sms_batches"."template")) BETWEEN 1 AND 1000),
	CONSTRAINT "sms_batches_counts" CHECK ("sms_batches"."sent_count" + "sms_batches"."failed_count" + "sms_batches"."skipped_count" <= "sms_batches"."total_count"),
	CONSTRAINT "sms_batches_stopped" CHECK ("sms_batches"."stopped_code" IS NULL OR "sms_batches"."stopped_code" ~ '^[a-z_]{1,64}$')
);
--> statement-breakpoint
CREATE TABLE "sms_messages" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "sms_messages_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"batch_id" bigint NOT NULL,
	"customer_id" bigint NOT NULL,
	"customer_code" text NOT NULL,
	"customer_name" text NOT NULL,
	"phone" text,
	"text" text NOT NULL,
	"balance" numeric(14, 2) NOT NULL,
	"status" text NOT NULL,
	"idempotency_key" uuid DEFAULT gen_random_uuid() NOT NULL,
	"provider_message_id" text,
	"parts" smallint,
	"credits" integer,
	"error_code" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"sent_at" timestamp with time zone,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "sms_messages_batch_customer" UNIQUE("batch_id","customer_id"),
	CONSTRAINT "sms_messages_status" CHECK ("sms_messages"."status" IN ('QUEUED', 'SENT', 'FAILED', 'SKIPPED')),
	CONSTRAINT "sms_messages_phone" CHECK ("sms_messages"."phone" IS NULL OR "sms_messages"."phone" ~ '^\+976[0-9]{8}$'),
	CONSTRAINT "sms_messages_error" CHECK ("sms_messages"."error_code" IS NULL OR "sms_messages"."error_code" ~ '^[a-z_]{1,64}$'),
	CONSTRAINT "sms_messages_outcome" CHECK (("sms_messages"."status" = 'SENT') = ("sms_messages"."sent_at" IS NOT NULL AND "sms_messages"."provider_message_id" IS NOT NULL)
        AND ("sms_messages"."status" IN ('FAILED', 'SKIPPED')) = ("sms_messages"."error_code" IS NOT NULL))
);
--> statement-breakpoint
CREATE TABLE "sms_settings" (
	"id" smallint PRIMARY KEY NOT NULL,
	"api_key_sealed" text,
	"enabled" boolean DEFAULT true NOT NULL,
	"updated_by" bigint,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "sms_settings_single" CHECK ("sms_settings"."id" = 1)
);
